# Total significant vs. non-significant comparisons, by predictor
by_indicator_6pred <- pred_pairs %>%
  group_by(covariate) %>%
  summarise(
    n_total       = n(),
    n_significant = sum(sig),
    n_nonsig      = sum(!sig)
